import type { UxIR } from "@smithable/core";

const HEADER =
  "/* Generated by Smithable from smithable.ux.yml. Do not edit: this file is overwritten on every change. */\n";

/**
 * The theme presets (ARCHITECTURE §10.4). Placeholders until the designer's presets arrive
 * (docs/design/brief.md): each is a hue and chroma for the primary colour and its tinted
 * neutrals, a corner radius and a font. Token names follow shadcn/ui.
 */
const PRESETS = {
  modern: {
    hue: 262,
    chroma: 0.17,
    lightness: 0.5,
    neutral: 0.02,
    radius: "0.625rem",
    font: "Inter",
  },
  minimal: {
    hue: 260,
    chroma: 0.01,
    lightness: 0.25,
    neutral: 0.006,
    radius: "0.375rem",
    font: undefined,
  },
  playful: {
    hue: 165,
    chroma: 0.13,
    lightness: 0.52,
    neutral: 0.02,
    radius: "1rem",
    font: "Nunito",
  },
  corporate: {
    hue: 255,
    chroma: 0.12,
    lightness: 0.42,
    neutral: 0.015,
    radius: "0.25rem",
    font: "IBM Plex Sans",
  },
} as const;

/** Fonts hosted by the app itself (Fontsource, OFL); the package is added to package.json. */
export const FONT_PACKAGES: Record<string, string> = {
  Inter: "@fontsource-variable/inter",
  Nunito: "@fontsource-variable/nunito",
  "IBM Plex Sans": "@fontsource-variable/ibm-plex-sans",
  "Source Sans 3": "@fontsource-variable/source-sans-3",
  "Merriweather Sans": "@fontsource-variable/merriweather-sans",
  Figtree: "@fontsource-variable/figtree",
};

/** The font the app uses: the brand's, or the preset's. */
export function themeFont(ux: UxIR): string | undefined {
  return ux.theme.font ?? PRESETS[ux.theme.preset].font;
}

/** "#2563eb" → OKLCH lightness (0-1), chroma and hue (degrees). */
export function hexToOklch(hex: string): { l: number; c: number; h: number } {
  const channel = (i: number) => {
    const v = Number.parseInt(hex.slice(1 + i * 2, 3 + i * 2), 16) / 255;
    return v <= 0.04045 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4;
  };
  const [r, g, b] = [channel(0), channel(1), channel(2)];
  const l = Math.cbrt(0.4122214708 * r + 0.5363325363 * g + 0.0514459929 * b);
  const m = Math.cbrt(0.2119034982 * r + 0.6806995451 * g + 0.1073969566 * b);
  const s = Math.cbrt(0.0883024619 * r + 0.2817188376 * g + 0.6299787005 * b);
  const L = 0.2104542553 * l + 0.793617785 * m - 0.0040720468 * s;
  const A = 1.9779984951 * l - 2.428592205 * m + 0.4505937099 * s;
  const B = 0.0259040371 * l + 0.7827717662 * m - 0.808675766 * s;
  const h = (Math.atan2(B, A) * 180) / Math.PI;
  return { l: L, c: Math.sqrt(A * A + B * B), h: h < 0 ? h + 360 : h };
}

const clamp = (v: number, min: number, max: number) => Math.min(max, Math.max(min, v));
const oklch = (l: number, c: number, h: number) =>
  `oklch(${l.toFixed(3)} ${c.toFixed(3)} ${Math.round(h)})`;

/**
 * The colour tokens for light or dark mode. Brand-input rules (placeholders): the brand
 * colour keeps its hue and chroma; its lightness is clamped so white text on it stays
 * readable in light mode and dark text in dark mode; the neutrals take its hue.
 */
function tokens(ux: UxIR, dark: boolean): Record<string, string> {
  const preset = PRESETS[ux.theme.preset];
  const brand = ux.theme.primary ? hexToOklch(ux.theme.primary) : undefined;
  const hue = brand ? brand.h : preset.hue;
  const chroma = brand ? Math.min(brand.c, 0.2) : preset.chroma;
  const n: number = preset.neutral;
  const primary = dark
    ? clamp(brand ? brand.l : preset.lightness + 0.2, 0.68, 0.8)
    : clamp(brand ? brand.l : preset.lightness, 0.3, 0.55);
  const neutral = (l: number, c = n) => oklch(l, c, hue);
  const common = {
    primary: oklch(primary, chroma, hue),
    "chart-1": oklch(primary, chroma, hue),
    "chart-2": oklch(dark ? 0.72 : 0.6, 0.12, (hue + 75) % 360),
    "chart-3": oklch(dark ? 0.72 : 0.6, 0.12, (hue + 150) % 360),
    "chart-4": oklch(dark ? 0.72 : 0.6, 0.12, (hue + 225) % 360),
    "chart-5": oklch(dark ? 0.72 : 0.6, 0.12, (hue + 300) % 360),
  };
  return dark
    ? {
        ...common,
        background: neutral(0.17, n * 0.6),
        foreground: neutral(0.95, n * 0.25),
        card: neutral(0.2, n * 0.7),
        "card-foreground": "var(--foreground)",
        "primary-foreground": neutral(0.17),
        secondary: neutral(0.26, n * 0.8),
        "secondary-foreground": neutral(0.93, n * 0.25),
        muted: neutral(0.24, n * 0.7),
        "muted-foreground": neutral(0.72, n * 0.75),
        accent: neutral(0.28, Math.min(chroma * 0.3, 0.05)),
        "accent-foreground": neutral(0.92, Math.min(chroma * 0.2, 0.03)),
        destructive: "oklch(0.64 0.2 25)",
        "destructive-foreground": "oklch(0.17 0.02 25)",
        success: "oklch(0.72 0.14 150)",
        "success-foreground": "oklch(0.17 0.02 150)",
        warning: "oklch(0.8 0.14 80)",
        "warning-foreground": "oklch(0.2 0.03 80)",
        border: neutral(0.29, n * 0.75),
        input: neutral(0.34, n * 0.8),
        ring: oklch(primary - 0.08, chroma * 0.85, hue),
        sidebar: neutral(0.19, n * 0.65),
      }
    : {
        ...common,
        background: neutral(0.985, n * 0.1),
        foreground: neutral(0.2),
        card: "oklch(1 0 0)",
        "card-foreground": "var(--foreground)",
        "primary-foreground": "oklch(0.985 0 0)",
        secondary: neutral(0.955, n * 0.3),
        "secondary-foreground": neutral(0.25),
        muted: neutral(0.96, n * 0.2),
        "muted-foreground": neutral(0.5),
        accent: neutral(0.95, Math.min(chroma * 0.12, 0.03)),
        "accent-foreground": neutral(0.3, Math.min(chroma * 0.5, 0.1)),
        destructive: "oklch(0.55 0.22 27)",
        "destructive-foreground": "oklch(0.985 0 0)",
        success: "oklch(0.5 0.14 150)",
        "success-foreground": "oklch(0.985 0 0)",
        warning: "oklch(0.55 0.14 70)",
        "warning-foreground": "oklch(0.985 0 0)",
        border: neutral(0.92, n * 0.3),
        input: neutral(0.88, n * 0.4),
        ring: oklch(primary + 0.1, chroma * 0.85, hue),
        sidebar: neutral(0.975, n * 0.2),
      };
}

/** src/theme.css: the colour, shape, font and density tokens the app kit's styles use. */
export function themeCss(ux: UxIR): string {
  const font = themeFont(ux);
  const block = (values: Record<string, string>, indent: string) =>
    Object.entries(values)
      .map(([k, v]) => `${indent}--${k}: ${v};`)
      .join("\n");
  const fontStack = `${font ? `"${font} Variable", ` : ""}ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif`;
  return `${HEADER}${font ? `@import "${FONT_PACKAGES[font]}";\n\n` : ""}/* Theme: ${ux.theme.preset}${ux.theme.primary ? `, brand colour ${ux.theme.primary}` : ""}${font ? `, font ${font}` : ""}, ${ux.theme.density} */
:root {
${block(tokens(ux, false), "  ")}
  --radius: ${PRESETS[ux.theme.preset].radius};
  --font-body: ${fontStack};${ux.theme.density === "compact" ? "\n  /* Compact: every Tailwind spacing step is a little smaller. */\n  --spacing: 0.21rem;" : ""}
}

@media (prefers-color-scheme: dark) {
  :root {
${block(tokens(ux, true), "    ")}
  }
}
`;
}
